style:
/* DM SOA dashboards v2 — Custom HTML Block (Style field). Same file for the Sales "SOA Request" block and Azrah's "SOA Manager" block.
 * Royal-blue top bar · flat grey surface with glass cards · coloured status tones · English / Arabic (RTL) · light + dark */

.soa {
  --royal:#2b4fc1; --royal-d:#223f9f; --royal-l:rgba(43,79,193,.10); --bar:#2b4fc1; --tab-on-bg:#fff; --tab-on-fg:#2b4fc1;
  --fg:#15202e; --mut:#566173; --line:rgba(30,45,70,.12); --sunk:rgba(40,60,100,.06);
  --glass:rgba(255,255,255,.72); --glass-hi:rgba(255,255,255,.94); --glass-bd:rgba(255,255,255,.95);
  --shadow:0 6px 22px rgba(40,50,80,.09), inset 0 1px 0 rgba(255,255,255,.9);
  --green:#0d6a44; --green-bg:rgba(13,106,68,.12); --amber:#8f4f06; --amber-bg:rgba(217,132,12,.16); --red:#ae2417; --red-bg:rgba(190,40,25,.12);
  --blue:#1a56c0; --blue-bg:rgba(26,86,192,.11); --r:18px; --gap:14px;
  container-type:inline-size; position:relative; isolation:isolate; border-radius:24px; padding:18px; min-height:70vh;
  color:var(--fg); background:#eceef2; font-size:13px; line-height:1.4; -webkit-font-smoothing:antialiased;
}
.soa.soa-dark {
  --royal:#6c8cf0; --royal-d:#4169e1; --royal-l:rgba(108,140,240,.16); --bar:#243f9e; --tab-on-bg:#20252f; --tab-on-fg:#fff;
  --fg:#eef2fa; --mut:#aab4c6; --line:rgba(255,255,255,.12); --sunk:rgba(255,255,255,.06);
  --glass:rgba(255,255,255,.065); --glass-hi:rgba(255,255,255,.11); --glass-bd:rgba(255,255,255,.14);
  --shadow:0 8px 26px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.08);
  --green:#5fd39a; --green-bg:rgba(60,200,140,.15); --amber:#ffc56b; --amber-bg:rgba(255,190,90,.15); --red:#ff9e94; --red-bg:rgba(255,120,105,.15);
  --blue:#8bb8ff; --blue-bg:rgba(100,150,255,.16); background:#15181e;
}
.soa *, .soa *::before, .soa *::after { box-sizing:border-box; }
.soa button, .soa input, .soa select, .soa textarea { font:inherit; color:inherit; }
.soa a { color:var(--royal); }

/* ---------- top bar ---------- */
.soa-top { display:flex; align-items:center; flex-wrap:wrap; gap:8px 14px; padding:6px; margin-bottom:var(--gap); border-radius:14px;
  background:var(--bar); box-shadow:0 6px 18px rgba(43,79,193,.28); position:relative; z-index:3; }
.soa-tabs { flex:1 1 auto; min-width:0; display:flex; gap:4px; overflow-x:auto; scrollbar-width:none; }
.soa-tabs::-webkit-scrollbar { display:none; }
.soa-tab { flex:0 0 auto; border:0; background:transparent; color:rgba(255,255,255,.86); border-radius:10px; padding:9px 16px; font-size:13px; font-weight:600; cursor:pointer; white-space:nowrap; display:inline-flex; align-items:center; gap:7px; transition:background .15s,color .15s; }
.soa-tab:hover { background:rgba(255,255,255,.14); color:#fff; }
.soa-tab.on { background:var(--tab-on-bg); color:var(--tab-on-fg); box-shadow:0 1px 3px rgba(10,20,60,.25); }
.soa-tab .soa-cnt { min-width:20px; height:20px; padding:0 6px; border-radius:10px; font-size:11px; line-height:20px; text-align:center; background:rgba(255,255,255,.22); color:#fff; }
.soa-tab.on .soa-cnt { background:var(--royal); color:#fff; }
.soa-tab .soa-cnt.hot { background:#f59e0b; color:#1f1300; }
.soa-side { flex:0 0 auto; display:flex; align-items:center; gap:10px; color:rgba(255,255,255,.9); font-size:12px; padding-inline:4px 2px; white-space:nowrap; }
.soa-me { display:inline-flex; align-items:center; gap:7px; }
.soa-me i { width:26px; height:26px; border-radius:50%; display:grid; place-items:center; background:rgba(255,255,255,.2); font-style:normal; font-weight:700; font-size:11px; }
.soa-ibtn { border:0; width:30px; height:30px; border-radius:10px; background:rgba(255,255,255,.16); color:#fff; font-size:16px; cursor:pointer; }
.soa-ibtn:hover { background:rgba(255,255,255,.28); }
.soa-lang { border:1px solid rgba(255,255,255,.4); background:transparent; color:#fff !important; height:30px; min-width:74px; padding:0 12px; border-radius:10px; font-size:12px; font-weight:600; cursor:pointer; }
.soa-lang:hover { background:rgba(255,255,255,.2); }
.soa-tab:focus-visible, .soa-lang:focus-visible, .soa-ibtn:focus-visible { outline:2px solid #fff; outline-offset:-3px; }
@container (max-width:520px) { .soa-tabs { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); overflow:visible; } .soa-tabs .soa-tab { justify-content:center; text-align:center; } .soa-col .soa-tabs { grid-template-columns:1fr; } }
@container (max-width:760px) { .soa-tabs { flex-basis:100%; } .soa-side { flex:1 1 100%; justify-content:space-between; padding:6px 6px 2px; border-top:1px solid rgba(255,255,255,.2); } }

.soa-pane { display:none; }
.soa-pane.on { display:block; animation:soa-fade .25s ease both; }
@keyframes soa-fade { from { opacity:0; } to { opacity:1; } }

/* ---------- surfaces ---------- */
.soa-card { border-radius:var(--r); background:var(--glass); border:1px solid var(--glass-bd); box-shadow:var(--shadow);
  -webkit-backdrop-filter:blur(18px) saturate(160%); backdrop-filter:blur(18px) saturate(160%); min-width:0; }
.soa-card-h { display:flex; align-items:center; justify-content:space-between; gap:10px; padding:14px 16px 6px; }
.soa-card-t { font-size:14.5px; font-weight:650; margin:0; }
.soa-card-s { font-size:12px; color:var(--mut); }
.soa-card-b { padding:6px 16px 16px; }
.soa-warnbar { margin-bottom:var(--gap); padding:10px 14px; border-radius:12px; background:var(--amber-bg); color:var(--amber); font-weight:550; }

/* ---------- KPIs ---------- */
.soa-kpis { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:var(--gap); margin-bottom:var(--gap); }
@container (max-width:620px) { .soa-kpis { grid-template-columns:repeat(2,minmax(0,1fr)); } }
.soa-kpi { position:relative; padding:14px 16px; text-align:center; }
.soa-kpi-i { width:32px; height:32px; margin:0 auto 6px; border-radius:50%; display:grid; place-items:center; color:#fff; background:var(--royal); }
.soa-kpi-i svg { width:16px; height:16px; }
.soa-kpi.green .soa-kpi-i { background:#1f8a5b; } .soa-kpi.amber .soa-kpi-i { background:#d08a17; } .soa-kpi.red .soa-kpi-i { background:#c2412f; }
.soa-kpi-l { font-size:12px; color:var(--mut); font-weight:550; }
.soa-kpi-v { font-size:28px; font-weight:650; letter-spacing:-.03em; line-height:1.15; font-variant-numeric:tabular-nums; }
.soa-kpi.amber .soa-kpi-v { color:var(--amber); } .soa-kpi.red .soa-kpi-v { color:var(--red); } .soa-kpi.green .soa-kpi-v { color:var(--green); }
.soa-kpi-s { font-size:11.5px; color:var(--mut); min-height:15px; }

/* ---------- new request layout ---------- */
.soa-split { display:grid; grid-template-columns:minmax(0,5fr) minmax(0,7fr); gap:var(--gap); align-items:start; }
@container (max-width:900px) { .soa-split { grid-template-columns:1fr; } }
.soa-search { display:flex; gap:8px; padding:0 16px 10px; }
.soa-in, .soa-sel, .soa-ta { height:36px; border-radius:10px; border:1px solid var(--line); background:var(--glass-hi); padding:0 12px; min-width:0; outline:none; }
.soa-in:focus, .soa-sel:focus, .soa-ta:focus { border-color:var(--royal); box-shadow:0 0 0 3px var(--royal-l); }
.soa-search .soa-in { flex:1; }
.soa-ta { height:auto; min-height:62px; width:100%; padding:9px 12px; resize:vertical; }
.soa-clist { max-height:620px; overflow:auto; padding:0 8px 10px; scrollbar-width:thin; }
.soa-c { width:100%; display:grid; grid-template-columns:minmax(0,1fr) auto; gap:2px 10px; text-align:start; border:1px solid transparent; background:transparent; border-radius:12px; padding:10px; cursor:pointer; }
.soa-c + .soa-c { margin-top:2px; }
.soa-c:hover { background:var(--glass-hi); }
.soa-c.on { background:var(--royal-l); border-color:var(--royal); }
.soa-c-n { font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.soa-c-a { font-weight:650; font-variant-numeric:tabular-nums; text-align:end; }
.soa-c-m { font-size:11.5px; color:var(--mut); overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.soa-c-b { display:flex; gap:4px; justify-content:flex-end; flex-wrap:wrap; }
.soa-brand { display:inline-block; padding:1px 8px; border-radius:999px; font-size:10.5px; font-weight:650; background:var(--royal-l); color:var(--royal); white-space:nowrap; }
.soa-brand.najd { background:rgba(13,106,68,.12); color:var(--green); }
.soa-brand.dmcc { background:rgba(124,58,237,.12); color:#6d3fd6; }
.soa.soa-dark .soa-brand.dmcc { color:#c4a9ff; background:rgba(160,120,255,.17); }
.soa-empty { padding:28px 12px; text-align:center; color:var(--mut); }
.soa-empty b { display:block; color:var(--fg); font-size:14px; margin-bottom:4px; }

.soa-sel-h { display:flex; align-items:flex-start; justify-content:space-between; gap:10px; padding:16px 16px 4px; }
.soa-sel-h h3 { margin:0; font-size:17px; font-weight:700; }
.soa-sel-h .soa-c-m { white-space:normal; }
.soa-bal { text-align:end; }
.soa-bal b { display:block; font-size:20px; font-variant-numeric:tabular-nums; }
.soa-step { padding:12px 16px 4px; }
.soa-step-t { font-size:12px; font-weight:650; color:var(--mut); margin:0 0 8px; }
.soa-opts { display:grid; grid-template-columns:repeat(auto-fit,minmax(200px,1fr)); gap:8px; }
@container (max-width:620px) { .soa-opts { grid-template-columns:1fr; } }
.soa-opt { display:flex; flex-direction:column; gap:3px; align-items:flex-start; text-align:start; padding:12px; border-radius:14px; border:1px solid var(--line); background:var(--glass-hi); cursor:pointer; transition:border-color .15s, background .15s; }
.soa-opt:hover { border-color:var(--royal); }
.soa-opt.on { border-color:var(--royal); background:var(--royal-l); box-shadow:inset 0 0 0 1px var(--royal); }
.soa-opt svg { width:20px; height:20px; color:var(--royal); margin-bottom:4px; }
.soa-opt b { font-size:13px; }
.soa-opt span { font-size:11.5px; color:var(--mut); }
.soa-dates { display:flex; flex-wrap:wrap; gap:8px; align-items:center; }
.soa-dates label { display:flex; align-items:center; gap:6px; font-size:12px; color:var(--mut); }
.soa-dates .soa-in { width:150px; }
.soa-pres { display:flex; flex-wrap:wrap; gap:6px; margin-top:8px; }
.soa-chipbtn { border:1px solid var(--line); background:var(--glass-hi); border-radius:999px; padding:4px 12px; font-size:12px; cursor:pointer; }
.soa-chipbtn:hover, .soa-chipbtn.on { background:var(--royal); color:#fff; border-color:var(--royal); }
.soa-lhs { display:flex; flex-wrap:wrap; gap:8px; }
.soa-lh { display:flex; flex-direction:column; gap:1px; padding:9px 12px; border-radius:12px; background:var(--sunk); min-width:140px; }
.soa-lh small { color:var(--mut); font-size:11.5px; }
.soa-check { display:flex; gap:9px; align-items:flex-start; margin:12px 16px 0; padding:10px 12px; border-radius:12px; font-size:12.5px; }
.soa-check svg { flex:none; width:18px; height:18px; margin-top:1px; }
.soa-check.ok { background:var(--green-bg); color:var(--green); }
.soa-check.warn { background:var(--amber-bg); color:var(--amber); }
.soa-act { display:flex; gap:10px; align-items:center; justify-content:flex-end; padding:14px 16px 16px; flex-wrap:wrap; }
.soa-btn { height:38px; padding:0 18px; border-radius:11px; border:1px solid var(--line); background:var(--glass-hi); font-weight:600; cursor:pointer; display:inline-flex; align-items:center; gap:7px; white-space:nowrap; }
.soa-btn:hover { border-color:var(--royal); }
.soa-btn.pri { background:var(--royal); border-color:var(--royal); color:#fff; }
.soa-btn.pri:hover { background:var(--royal-d); }
.soa-btn.ok { background:#1f8a5b; border-color:#1f8a5b; color:#fff; }
.soa-btn.bad { color:var(--red); }
.soa-btn:disabled { opacity:.55; cursor:not-allowed; }
.soa-btn.sm { height:30px; padding:0 12px; font-size:12px; border-radius:9px; }
.soa-res { margin:0 16px 16px; padding:12px 14px; border-radius:12px; }
.soa-res.ok { background:var(--green-bg); color:var(--green); }
.soa-res.warn { background:var(--amber-bg); color:var(--amber); }
.soa-res.bad { background:var(--red-bg); color:var(--red); }
.soa-res b { display:block; margin-bottom:4px; }
.soa-files { display:flex; flex-wrap:wrap; gap:6px; }
.soa-file { display:inline-flex; align-items:center; gap:5px; padding:3px 10px; border-radius:999px; background:var(--royal-l); color:var(--royal) !important; font-size:11.5px; font-weight:600; text-decoration:none; white-space:nowrap; }
.soa-file:hover { background:var(--royal); color:#fff !important; }
.soa-file svg { width:13px; height:13px; }

/* ---------- tables / log ---------- */
.soa-tools { display:flex; flex-wrap:wrap; gap:8px; align-items:center; padding:0 16px 10px; }
.soa-tools .soa-in { flex:1 1 200px; }
.soa-scroll { overflow:auto; max-height:640px; scrollbar-width:thin; }
.soa-t { width:100%; border-collapse:collapse; font-size:12.5px; }
.soa-t th { position:sticky; top:0; z-index:1; text-align:start; font-weight:550; font-size:12px; color:var(--mut); padding:8px 12px; white-space:nowrap; background:#e4e7ee; border-block:1px solid var(--line); }
.soa.soa-dark .soa-t th { background:#1f232b; }
.soa-t td { padding:9px 12px; border-bottom:1px solid var(--line); vertical-align:middle; }
.soa-t tbody tr:hover { background:var(--glass-hi); }
.soa-t .n { text-align:end; font-variant-numeric:tabular-nums; white-space:nowrap; }
.soa-t .nw { white-space:nowrap; }
.soa-t small { color:var(--mut); }
.soa-b { display:inline-block; padding:2px 10px; border-radius:999px; font-size:11.5px; font-weight:600; white-space:nowrap; }
.soa-b.green { background:var(--green-bg); color:var(--green); } .soa-b.amber { background:var(--amber-bg); color:var(--amber); }
.soa-b.red { background:var(--red-bg); color:var(--red); } .soa-b.blue { background:var(--blue-bg); color:var(--blue); } .soa-b.grey { background:var(--sunk); color:var(--mut); }
.soa-neg { color:var(--red); font-weight:650; }

/* ---------- review queue (manager) ---------- */
.soa-queue { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:var(--gap); }
@container (max-width:1000px) { .soa-queue { grid-template-columns:1fr; } }
.soa-q-h { display:flex; justify-content:space-between; gap:12px; padding:14px 16px 4px; }
.soa-q-h h3 { margin:0; font-size:15px; font-weight:700; }
.soa-q-st { text-align:end; flex:none; }
.soa-q-st .soa-card-s { margin-top:4px; }
.soa-q-meta { display:flex; flex-wrap:wrap; gap:6px 14px; padding:2px 16px 8px; font-size:12px; color:var(--mut); }
.soa-trio { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:8px; padding:4px 16px 8px; }
.soa-trio > div { padding:10px 12px; border-radius:12px; background:var(--sunk); }
.soa-trio small { display:block; color:var(--mut); font-size:11.5px; }
.soa-trio b { font-size:16px; font-variant-numeric:tabular-nums; }
.soa-trio .bad { background:var(--red-bg); } .soa-trio .bad b { color:var(--red); }
.soa-why { margin:0 16px 8px; border-radius:12px; border:1px solid var(--line); overflow:hidden; }
.soa-why-h { padding:8px 12px; font-size:12px; font-weight:650; background:var(--sunk); }
.soa-why ul { list-style:none; margin:0; padding:0; }
.soa-why li { display:grid; grid-template-columns:minmax(0,1fr) auto; gap:2px 10px; padding:8px 12px; border-top:1px solid var(--line); font-size:12.5px; }
.soa-why li small { color:var(--mut); grid-column:1; }
.soa-why .n { grid-row:1 / span 2; grid-column:2; align-self:center; font-weight:650; font-variant-numeric:tabular-nums; }
.soa-q-files { display:flex; flex-wrap:wrap; gap:6px; align-items:center; padding:0 16px 8px; font-size:12px; color:var(--mut); }
.soa-q-act { padding:4px 16px 16px; display:grid; gap:8px; }
.soa-q-act .soa-ta { min-height:44px; }
.soa-q-btns { display:flex; gap:8px; flex-wrap:wrap; justify-content:flex-end; }
.soa-note { margin:0 16px 8px; padding:8px 12px; border-radius:10px; background:var(--sunk); font-size:12px; }
.soa-err { margin:0 16px 8px; padding:8px 12px; border-radius:10px; background:var(--red-bg); color:var(--red); font-size:12px; }

.soa-skel { height:120px; margin:10px 16px 16px; border-radius:12px; background:linear-gradient(100deg,var(--sunk) 30%,var(--glass-hi) 50%,var(--sunk) 70%); background-size:220% 100%; animation:soa-sh 1.3s linear infinite; }
@keyframes soa-sh { from { background-position:120% 0; } to { background-position:-120% 0; } }
.soa-spin { width:14px; height:14px; border-radius:50%; border:2px solid currentColor; border-right-color:transparent; animation:soa-rot .7s linear infinite; display:inline-block; }
@keyframes soa-rot { to { transform:rotate(360deg); } }
.soa-toast { position:fixed; inset-inline-end:24px; bottom:24px; z-index:50; padding:11px 16px; border-radius:12px; color:#fff; background:#1f2937; box-shadow:0 10px 30px rgba(0,0,0,.25); font-weight:550; max-width:360px; }
.soa-toast.ok { background:#1f8a5b; } .soa-toast.bad { background:#b42318; }
@supports not ((backdrop-filter:blur(1px)) or (-webkit-backdrop-filter:blur(1px))) { .soa-card { background:var(--glass-hi); } }

/* ---------- statement date hint, General Ledger check (manager) ---------- */
.soa-hint { margin:8px 0 0; font-size:12px; color:var(--mut); }
.soa-glh { display:flex; justify-content:space-between; align-items:center; gap:10px; flex-wrap:wrap; }
.soa-glh a { font-weight:600; font-size:12px; text-decoration:none; }
.soa-mini-w { overflow-x:auto; }
.soa-mini { width:100%; border-collapse:collapse; font-size:12px; font-variant-numeric:tabular-nums; }
.soa-mini th, .soa-mini td { padding:7px 12px; border-top:1px solid var(--line); text-align:end; white-space:nowrap; }
.soa-mini thead th { color:var(--mut); font-weight:550; font-size:11.5px; }
.soa-mini tbody th { text-align:start; font-weight:600; }
.soa-mini tr.bad td { color:var(--red); font-weight:650; }
.soa-mini tr.bad td:last-child { background:var(--red-bg); }

/* ---------- phones ---------- */
@media (max-width:640px) {
  .soa { padding:10px; border-radius:16px; min-height:0; }
  .soa-toast { inset-inline:12px; bottom:12px; max-width:none; text-align:center; }
}
@container (max-width:640px) {
  .soa-top { padding:5px; margin-bottom:10px; }
  .soa-tab { padding:8px 12px; }
  .soa-kpis { gap:10px; margin-bottom:10px; }
  .soa-split, .soa-queue { gap:10px; }
  .soa-kpi { padding:10px 8px; }
  .soa-kpi-v { font-size:22px; }
  .soa-kpi-s { font-size:11px; }
  .soa-in, .soa-sel, .soa-ta { font-size:16px; height:42px; }   /* 16px stops iPhone zooming into the field */
  .soa-ta { height:auto; }
  .soa-search { padding:0 12px 10px; }
  .soa-search .soa-sel { max-width:44%; }
  .soa-clist { max-height:46vh; }
  .soa-c { padding:12px 10px; }
  .soa-card-h { padding:12px 12px 6px; }
  .soa-sel-h { flex-wrap:wrap; padding:14px 12px 4px; }
  .soa-step { padding:12px 12px 4px; }
  .soa-check { margin:12px 12px 0; }
  .soa-dates { display:grid; grid-template-columns:repeat(auto-fit,minmax(140px,1fr)); }
  .soa-dates label { flex-direction:column; align-items:stretch; gap:4px; }
  .soa-dates .soa-in { width:100%; }
  .soa-act { padding:14px 12px 14px; }
  .soa-act .soa-btn, .soa-q-btns .soa-btn { flex:1 1 auto; justify-content:center; }
  .soa-act .soa-btn { height:46px; }
  .soa-q-btns .soa-btn.sm { height:40px; }
  .soa-res { margin:0 12px 12px; }
  .soa-q-h, .soa-q-meta, .soa-trio, .soa-q-act, .soa-q-files { padding-inline:12px; }
  .soa-q-h { flex-wrap:wrap; }
  .soa-why, .soa-note, .soa-err { margin-inline:12px; }
  .soa-trio { gap:6px; }
  .soa-trio > div { padding:8px; }
  .soa-trio b { font-size:13.5px; }
